#!/bin/sh
# Name: Embrith SSH
# Author: Embrith Contributors
# DontUseFBInk
# Icon: data:image/png;base64,
#
# 前台运行(不分离进程, 脚本不结束 Kindle 就认为它还在运行, 不会重绘图书馆盖住页面). SSH 页面(不启动安卓): 每个来源(Embrith, KOReader)一个开关和端口, 触摸操作. 点 EXIT 回到 Kindle.
D=/mnt/us/system/embrith; S=/mnt/us/embrith; mkdir -p $S/logs
{ echo "== $(date)"; sh $D/modules/lib/ssh-page.sh; echo "== done"; } >> $S/logs/ssh-page.log 2>&1
